/** User-provided Nuvio example, resized for the Preferences preview. */
const encoded="";
let image:Uint8Array;
export function reviewPreviewImage(){image??=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));return new Response(image,{headers:{"content-type":"image/jpeg","cache-control":"public,max-age=86400","x-content-type-options":"nosniff"}});}
